head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldstf37033";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_comName", fn: function () { return String((dma_pageContext.get("comName") ?? "")); } },
        { childId: "cal_endDate", fn: function () { return String((dma_pageContext.get("endDate") ?? "")); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function () {
    if ('null' === '' && 'null' === '') {
        setPeriod('60');
    }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldstf37033.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name rd_month_onclick
 * @description rd_month 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.rd_month_onclick = function(e){
    try {
        setPeriod(12)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf37033.rd_month_onclick' }); }
};scwin.btn_submit_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        await scwin.submit()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf37033.btn_submit_onclick' }); }
};

/**
 * @method
 * @name btn_viewNews_onclick
 * @description btn_viewNews 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_viewNews_onclick = function(e){
    try {
        viewNews('')

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf37033.btn_viewNews_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_submit
 * @description submit 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_submit = async function () {
    const sbmOptions = {
        id: "tx_submit",
        method: "post",
        action: "/dsclmgt/JLDSTF37033.jsp",
        ref: "dma_submitReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name submit
 * @description submit 처리
 * @param {*} mode mode
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.submit = async function (mode) {
    const f = (document.form || { elements: [] });
    f.action = "/dsclmgt/JLDSTF37033.jsp";
    if (mode === null) {
        $c.util.getComponent('dma_submitReq').set('newsScrollY', "");
        $c.util.getComponent('dma_submitReq').set('pageNum', "1");
    }
    $c.util.getComponent('dma_submitReq').set('comName', encodeURIComponent($c.util.getComponent('dma_submitReq').get('comName')));
    await scwin.tx_submit();
};

/**
 * @method
 * @name findPosY
 * @description find Pos Y 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.findPosY = function (obj) {
    /* empty */
};

/**
 * @method
 * @name pageNav
 * @description page Nav 처리
 * @param {*} funcName funcName
 * @param {*} pageNum pageNum
 * @param {*} pageSize pageSize
 * @param {*} total total
 * @returns {void}
 * @hidden N
 */
scwin.pageNav = function (funcName, pageNum, pageSize, total) {
    if (total < 1) {
        return "";
    }
    let ret = "";
    const PAGEBLOCK = 10;
    const totalPages = Math.floor((total - 1) / pageSize) + 1;
    let firstPage = Math.floor((pageNum - 1) / PAGEBLOCK) * PAGEBLOCK + 1;
    if (firstPage <= 0) {
        firstPage = 1;
    }
    let lastPage = firstPage - 1 + PAGEBLOCK;
    if (lastPage > totalPages) {
        lastPage = totalPages;
    }
    if (firstPage > PAGEBLOCK) {
        ret += navAnchor(funcName, 1, "<<처음") + "&nbsp;\n";
        ret += navAnchor(funcName, (firstPage - 1), "<이전") + "&nbsp;\n";
    }
    for (i = firstPage; i <= lastPage; i++) {
        if (pageNum === i) {
            ret += "<a class='active' onclick='return false;' href='#page_link_" + 1 + "'>" + i + "</a>&nbsp;\n";
        } else {
            ret += navAnchor(funcName, i, i) + "&nbsp;\n";
        }
    }
    if (lastPage < totalPages) {
        ret += navAnchor(funcName, (lastPage + 1), "다음>") + "&nbsp;\n";
        ret += "&nbsp;" + navAnchor(funcName, totalPages, "끝>>") + "\n";
    }
    return ret;
};
